c.python:
class Solution:
    def convertTemperature(self, celsius):
        k = round(celsius + 273.15, 5)
        f = round(celsius * 1.8 + 32.0, 5)
        return [k, f]

c.cpp:
class Solution {
public:
    vector<double> convertTemperature(double celsius){
        double k = celsius + 273.15;
        double f = celsius * 1.8 + 32.0;
        return vector<double>{k, f};
    }
};

c.java:
class Solution {
    public double[] convertTemperature(double celsius){
        double k = Math.round((celsius+273.15)*1e5)/1e5;
        double f = Math.round((celsius*1.8+32.0)*1e5)/1e5;
        return new double[]{k,f};
    }
}

c.javascript:
var convertTemperature = function(celsius) {
    const k = +(celsius+273.15).toFixed(5);
    const f = +(celsius*1.8+32.0).toFixed(5);
    return [k,f];
};
